set-variable.value:
@{
                try {
                    var body = context.Response.Body.As<JObject>(preserveContent: true);
                    if (body == null) { return "[]"; }

                    var measurements = new JArray();
                    foreach (var pair in "{{aforo-compound-extraction-paths}}".Split(new[] { ";" }, StringSplitOptions.RemoveEmptyEntries)) {
                        var idx = pair.LastIndexOf("=");
                        if (idx <= 0) { continue; }
                        var jsonPath = pair.Substring(0, idx).Trim();
                        var metricName = pair.Substring(idx + 1).Trim();
                        var token = body.SelectToken(jsonPath);
                        if (token != null && (token.Type == JTokenType.Integer || token.Type == JTokenType.Float)) {
                            var val = (double)token;
                            if (val > 0) {
                                var m = new JObject();
                                m["metricName"] = metricName;
                                m["quantity"] = val;
                                foreach (var dpair in "{{aforo-compound-dimension-paths}}".Split(new[] { ";" }, StringSplitOptions.RemoveEmptyEntries)) {
                                    var didx = dpair.LastIndexOf("=");
                                    if (didx <= 0) { continue; }
                                    var dimToken = body.SelectToken(dpair.Substring(0, didx).Trim());
                                    if (dimToken != null && dimToken.Type == JTokenType.String) {
                                        m["dimensionKey"] = dimToken.ToString();
                                        break;
                                    }
                                }
                                measurements.Add(m);
                            }
                        }
                    }
                    return measurements.ToString(Newtonsoft.Json.Formatting.None);
                } catch (Exception) {
                    return "[]";
                }
            }

send-one-way-request.set-body:
@{
                            var measurements = context.Variables.GetValueOrDefault<string>("compoundMeasurements");
                            var evt = new JObject();
                            evt["correlationId"] = context.RequestId.ToString();
                            evt["customerId"] = context.Variables.GetValueOrDefault<string>("aforo-customer-id", "");
                            evt["occurredAt"] = DateTime.UtcNow.ToString("o");
                            evt["measurements"] = JArray.Parse(measurements);
                            evt["metadata"] = new JObject {
                                ["gateway"] = "azure-apim",
                                ["apiId"] = context.Api != null ? context.Api.Id : "",
                                ["operationId"] = context.Operation != null ? context.Operation.Id : "",
                                ["statusCode"] = context.Response.StatusCode.ToString()
                            };
                            return evt.ToString(Newtonsoft.Json.Formatting.None);
                        }
